alter table public.animals add column if not exists notes text;
create table if not exists public.animal_weights (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, farm_id uuid not null references public.farms(id) on delete cascade, animal_id uuid not null references public.animals(id) on delete cascade, weight_kg numeric(10,2) not null check (weight_kg > 0), measured_at date not null default current_date, notes text, created_by uuid references auth.users(id) default auth.uid(), created_at timestamptz not null default now());
create table if not exists public.animal_health_events (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, farm_id uuid not null references public.farms(id) on delete cascade, animal_id uuid references public.animals(id) on delete cascade, event_type text not null, event_date date not null default current_date, product text, dose text, provider text, withdrawal_until date, notes text, created_by uuid references auth.users(id) default auth.uid(), created_at timestamptz not null default now());
create table if not exists public.protocols (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, name text not null, description text, active boolean not null default true, created_at timestamptz not null default now(), unique(organization_id,name));
create table if not exists public.protocol_steps (id uuid primary key default gen_random_uuid(), protocol_id uuid not null references public.protocols(id) on delete cascade, day_offset integer not null default 0, name text not null, instructions text, unique(protocol_id,day_offset));
create table if not exists public.reproductive_exposures (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, farm_id uuid not null references public.farms(id) on delete cascade, name text not null, start_date date not null, end_date date not null, method text, bull_or_semen text, notes text, created_at timestamptz not null default now(), check(end_date >= start_date));
alter table public.animal_weights enable row level security; alter table public.animal_health_events enable row level security; alter table public.protocols enable row level security; alter table public.protocol_steps enable row level security; alter table public.reproductive_exposures enable row level security;
create policy weights_members_read on public.animal_weights for select using (public.is_org_member(organization_id)); create policy weights_managers_write on public.animal_weights for all using (public.has_org_role(organization_id,array['owner','admin','manager','operator']::public.app_role[])) with check (public.has_org_role(organization_id,array['owner','admin','manager','operator']::public.app_role[]));
create policy health_members_read on public.animal_health_events for select using (public.is_org_member(organization_id)); create policy health_managers_write on public.animal_health_events for all using (public.has_org_role(organization_id,array['owner','admin','manager','operator']::public.app_role[])) with check (public.has_org_role(organization_id,array['owner','admin','manager','operator']::public.app_role[]));
create policy protocols_members_read on public.protocols for select using (public.is_org_member(organization_id)); create policy protocols_managers_write on public.protocols for all using (public.has_org_role(organization_id,array['owner','admin','manager']::public.app_role[])) with check (public.has_org_role(organization_id,array['owner','admin','manager']::public.app_role[]));
create policy protocol_steps_members_read on public.protocol_steps for select using (exists(select 1 from public.protocols p where p.id=protocol_id and public.is_org_member(p.organization_id))); create policy protocol_steps_managers_write on public.protocol_steps for all using (exists(select 1 from public.protocols p where p.id=protocol_id and public.has_org_role(p.organization_id,array['owner','admin','manager']::public.app_role[]))) with check (exists(select 1 from public.protocols p where p.id=protocol_id and public.has_org_role(p.organization_id,array['owner','admin','manager']::public.app_role[])));
create policy exposures_members_read on public.reproductive_exposures for select using (public.is_org_member(organization_id)); create policy exposures_managers_write on public.reproductive_exposures for all using (public.has_org_role(organization_id,array['owner','admin','manager','operator']::public.app_role[])) with check (public.has_org_role(organization_id,array['owner','admin','manager','operator']::public.app_role[]));
create index animal_weights_lookup on public.animal_weights(organization_id,animal_id,measured_at desc); create index health_events_lookup on public.animal_health_events(organization_id,animal_id,event_date desc); create index exposures_lookup on public.reproductive_exposures(organization_id,start_date desc);
